INSERT INTO grammar_points
  (id, language_id, slug, title, pattern, level_id, category, register, meaning_short, meaning_long, nuance, status, published, sort_index) VALUES
  ('gp-ni-kakawarazu', 'lang-ja', 'ni-kakawarazu', '〜にかかわらず', 'Noun / Plain form + にかかわらず', 'lvl-ja-n2', 'conjunction', 'formal', 'Regardless of.', '天候にかかわらず、決行します. Often with paired opposites: 経験の有無にかかわらず.', 'Distinct from 〜にもかかわらず ("despite"), which concedes one specific fact. にかかわらず dismisses a whole range of them.', 'in-review', true, 300),
  ('gp-nimo-kakawarazu', 'lang-ja', 'nimo-kakawarazu', '〜にもかかわらず', 'Plain form / Noun + にもかかわらず', 'lvl-ja-n2', 'conjunction', 'formal', 'Despite.', '雨にもかかわらず、大勢集まった.', 'The も is what narrows it to one conceded fact. Stronger and more written than のに, and without のに''s note of grievance.', 'in-review', true, 301),
  ('gp-wo-towazu', 'lang-ja', 'wo-towazu', '〜を問わず', 'Noun + を問わず', 'lvl-ja-n2', 'expression', 'formal', 'Irrespective of.', '年齢、性別を問わず応募できます.', '問う is to ask, so it literally says the question is not put. The natural home of job adverts and public notices.', 'in-review', true, 302),
  ('gp-wo-mondai-ni', 'lang-ja', 'wo-kiniseze', '〜をものともせず', 'Noun + をものともせず', 'lvl-ja-n2', 'expression', 'formal', 'Undaunted by.', '大けがをものともせず、出場した.', 'Admiring, and only about someone else — using it about yourself claims your own bravery. Reserved for genuine adversity.', 'in-review', true, 303),
  ('gp-wo-kawakiri-ni', 'lang-ja', 'wo-kawakiri-ni', '〜を皮切りに', 'Noun + を皮切りに', 'lvl-ja-n2', 'expression', 'formal', 'Starting with — and then spreading.', '東京を皮切りに、全国ツアーが始まった.', 'It needs what follows to expand. A single event with no sequel cannot be a 皮切り.', 'in-review', true, 304),
  ('gp-wo-komete', 'lang-ja', 'wo-komete', '〜を込めて', 'Noun + を込めて', 'lvl-ja-n2', 'expression', 'polite', 'With (a feeling) put into it.', '心を込めて作りました. 感謝を込めて.', 'Only for feelings, never for ingredients. It says the emotion was deliberately invested in the act.', 'in-review', true, 305),
  ('gp-wo-megutte', 'lang-ja', 'wo-megutte', '〜をめぐって', 'Noun + をめぐって', 'lvl-ja-n2', 'expression', 'formal', 'Over — the thing being argued about.', '土地の権利をめぐって争っている.', '巡る is to go around, and the disputants circle the issue. It nearly always introduces conflict, which について does not.', 'in-review', true, 306),
  ('gp-ni-motozuite', 'lang-ja', 'ni-motozuite', '〜に基づいて', 'Noun + に基づいて', 'lvl-ja-n2', 'expression', 'formal', 'Based on.', '事実に基づいて判断する.', 'The basis must be something solid — data, law, evidence. For a mere starting point, 〜をもとに is the looser word.', 'in-review', true, 307),
  ('gp-wo-moto-ni', 'lang-ja', 'wo-moto-ni', '〜をもとに', 'Noun + をもとに', 'lvl-ja-n2', 'expression', 'formal', 'On the basis of, using as material.', '実話をもとに書かれた小説.', 'The result may depart from the source, which に基づいて does not allow. A novel based on true events is をもとに precisely because it invents.', 'in-review', true, 308),
  ('gp-ni-oujite', 'lang-ja', 'ni-oujite', '〜に応じて', 'Noun + に応じて', 'lvl-ja-n2', 'expression', 'formal', 'In response to, varying with.', '収入に応じて、税額が変わる.', 'The second thing adjusts to the first. によって also covers variation, but に応じて implies a deliberate, proportionate response.', 'in-review', true, 309),
  ('gp-ni-wataru', 'lang-ja', 'ni-wataru', '〜にわたって', 'Noun + にわたって', 'lvl-ja-n2', 'expression', 'formal', 'Spanning, over the whole of.', '三年にわたって調査した. 全国にわたる.', 'For extent — time, area, scope. It stresses how much ground was covered, which is why it takes plural or measured nouns.', 'in-review', true, 310),
  ('gp-ni-kanshite', 'lang-ja', 'ni-kanshite', '〜に関して', 'Noun + に関して', 'lvl-ja-n2', 'particle', 'formal', 'Regarding.', 'その件に関しては、後ほど説明します.', 'The formal について. Slightly broader, admitting anything connected rather than only the subject itself.', 'in-review', true, 311),
  ('gp-ni-sotte', 'lang-ja', 'ni-sotte', '〜に沿って', 'Noun + に沿って', 'lvl-ja-n2', 'expression', 'formal', 'Along, in line with.', '川に沿って歩く. 方針に沿って進める.', 'One verb, two scales: following a riverbank and following a policy are the same motion. 沿う keeps contact with something that has a course.', 'in-review', true, 312),
  ('gp-ni-hanshite', 'lang-ja', 'ni-hanshite', '〜に反して', 'Noun + に反して', 'lvl-ja-n2', 'expression', 'formal', 'Contrary to.', '予想に反して、雨が降らなかった.', 'It needs something that had been expected or asserted — a prediction, a rule, an intention. It cannot simply contrast two facts.', 'in-review', true, 313),
  ('gp-ni-kagirazu', 'lang-ja', 'ni-kagirazu', '〜に限らず', 'Noun + に限らず', 'lvl-ja-n2', 'expression', 'formal', 'Not limited to.', '日本に限らず、世界中で問題になっている.', 'The negative of 〜に限り. It widens the claim, so the second half almost always carries も.', 'in-review', true, 314),
  ('gp-ni-kagiri', 'lang-ja', 'ni-kagiri', '〜に限り', 'Noun + に限り', 'lvl-ja-n2', 'expression', 'formal', 'Only in the case of.', '先着百名様に限り、無料です.', 'The register of terms and conditions. It grants an exception to a named group and to nobody else.', 'in-review', true, 315),
  ('gp-hanmen', 'lang-ja', 'hanmen', '〜反面', 'Plain form + 反面', 'lvl-ja-n2', 'conjunction', 'formal', 'On the other hand.', '便利な反面、値段が高い.', 'Both halves must describe the same thing. It is one subject with two faces, not two subjects compared.', 'in-review', true, 316),
  ('gp-ippou-de', 'lang-ja', 'ippou-de', '〜一方で', 'Plain form + 一方で', 'lvl-ja-n2', 'conjunction', 'formal', 'While on the other hand.', '経済は回復する一方で、格差は広がった.', 'Wider than 反面: the two halves may be about different subjects. 〜一方だ is a separate use meaning a trend only increases.', 'in-review', true, 317),
  ('gp-mono-nara', 'lang-ja', 'mono-nara', '〜ものなら', 'Potential + ものなら', 'lvl-ja-n2', 'conjunction', 'casual', 'If only it were possible.', '帰れるものなら帰りたい.', 'It supposes something the speaker believes cannot happen, which is why it takes the potential form and reads as longing.', 'in-review', true, 318),
  ('gp-you-mono-nara', 'lang-ja', 'you-mono-nara', '〜ようものなら', 'Volitional + ものなら', 'lvl-ja-n2', 'conjunction', 'formal', 'If you were to — and it would be bad.', '遅刻しようものなら、大変なことになる.', 'A warning, not a supposition. The consequence is always dire, which distinguishes it from the wistful 〜ものなら.', 'in-review', true, 319),
  ('gp-to-ittemo', 'lang-ja', 'to-ittemo', '〜といっても', 'Plain form + といっても', 'lvl-ja-n2', 'conjunction', 'casual', 'Although I say — it''s less than it sounds.', '料理といっても、卵を焼いただけです.', 'It walks back a claim the speaker just made themselves, heading off an overestimate.', 'in-review', true, 320),
  ('gp-to-wa-ie', 'lang-ja', 'towa-ie', '〜とはいえ', 'Plain form + とはいえ', 'lvl-ja-n2', 'conjunction', 'formal', 'That said.', '春とはいえ、まだ寒い.', 'Concedes what was just established, then contradicts it. The written cousin of といっても, and rather more literary.', 'in-review', true, 321),
  ('gp-kara-to-itte', 'lang-ja', 'kara-to-itte', '〜からといって', 'Plain form + からといって', 'lvl-ja-n2', 'conjunction', 'casual', 'Just because — that doesn''t follow.', '安いからといって、質が悪いとは限らない.', 'It rejects an inference, so the second half is nearly always negative — とは限らない, わけではない, ない.', 'in-review', true, 322),
  ('gp-towa-kagiranai', 'lang-ja', 'towa-kagiranai', '〜とは限らない', 'Plain form + とは限らない', 'lvl-ja-n2', 'expression', 'polite', 'Not necessarily.', '高いものがいいとは限らない.', 'It denies that something always holds, without denying that it often does. A weaker denial than わけではない.', 'in-review', true, 323),
  ('gp-ni-suginai', 'lang-ja', 'ni-suginai', '〜にすぎない', 'Plain form / Noun + にすぎない', 'lvl-ja-n2', 'expression', 'formal', 'Is no more than.', '推測にすぎない.', 'It belittles what it follows, usually to head off someone treating it as more solid than it is.', 'in-review', true, 324),
  ('gp-ni-hokanaranai', 'lang-ja', 'ni-hokanaranai', '〜にほかならない', 'Noun + にほかならない', 'lvl-ja-n2', 'expression', 'formal', 'Is nothing other than.', '成功は努力の結果にほかならない.', 'An emphatic identification: this and nothing else. Essays use it to close an argument.', 'in-review', true, 325),
  ('gp-nakattara', 'lang-ja', 'nashi-ni', '〜なしに', 'Noun + なしに', 'lvl-ja-n2', 'expression', 'formal', 'Without.', '許可なしに入ってはいけない.', 'The written 〜ないで for nouns. なしでは is its conditional twin: それなしでは生きられない.', 'in-review', true, 326),
  ('gp-nuki-ni', 'lang-ja', 'nuki-ni', '〜抜きに', 'Noun + 抜きに', 'lvl-ja-n2', 'expression', 'polite', 'Leaving out, dispensing with.', '冗談抜きに、本気です. わさび抜きで.', '抜く is to pull out, so it removes something that would normally be included — which is why it works both for formalities and for wasabi.', 'in-review', true, 327),
  ('gp-kiri-ga-nai', 'lang-ja', 'kkiri', '〜きり', 'Verb-た / Noun + きり', 'lvl-ja-n2', 'particle', 'casual', 'Only that, and nothing since.', '出て行ったきり、帰ってこない. 二人きり.', 'The た-form use marks a last occurrence with no sequel, which is why it so often carries loss.', 'in-review', true, 328),
  ('gp-shidai', 'lang-ja', 'shidai', '〜次第', 'Verb stem + 次第', 'lvl-ja-n2', 'expression', 'formal', 'As soon as.', '着き次第、ご連絡します. Also as a noun: 天気次第, "depends on the weather".', 'The "as soon as" use cannot take a past tense — it is always about something not yet done, which is why business Japanese uses it for promises.', 'in-review', true, 329),
  ('gp-ka-ina-ka', 'lang-ja', 'ka-ina-ka', '〜か否か', 'Plain form + か否か', 'lvl-ja-n2', 'expression', 'formal', 'Whether or not.', '実現するか否かは、まだ分からない.', 'The written かどうか. 否 is the classical negative, kept alive almost entirely by this phrase.', 'in-review', true, 330),
  ('gp-you-ni-mo', 'lang-ja', 'you-ni-mo', '〜ようにも〜ない', 'Volitional + にも + potential-ない', 'lvl-ja-n2', 'expression', 'formal', 'Even trying to, one cannot.', '休もうにも休めない.', 'The same verb appears twice, volitional then negative potential. It reports a wish blocked by circumstance rather than by unwillingness.', 'in-review', true, 331),
  ('gp-dokoro-ka', 'lang-ja', 'dokoro-ka', '〜どころか', 'Plain form / Noun + どころか', 'lvl-ja-n2', 'conjunction', 'casual', 'Far from — quite the opposite.', '謝るどころか、笑っていた.', 'It overturns the first half rather than qualifying it. The second half is often more extreme, not merely different.', 'in-review', true, 332),
  ('gp-dokoro-dewa-nai', 'lang-ja', 'dokoro-dewa-nai', '〜どころではない', 'Plain form / Noun + どころではない', 'lvl-ja-n2', 'expression', 'casual', 'This is no time for.', '旅行どころではない.', 'It rules something out on grounds of circumstance, not preference — there are more pressing things.', 'in-review', true, 333),
  ('gp-bakari-ka', 'lang-ja', 'bakari-ka', '〜ばかりか', 'Plain form / Noun + ばかりか', 'lvl-ja-n2', 'conjunction', 'formal', 'Not only — but even.', '雨ばかりか、風まで強くなってきた.', 'The second half escalates, usually marked by まで or さえ. Stronger than だけでなく, which merely adds.', 'in-review', true, 334),
  ('gp-mono-dakara', 'lang-ja', 'mono-dakara', '〜ものだから', 'Plain form + ものだから', 'lvl-ja-n2', 'conjunction', 'casual', 'Because — offered as an excuse.', '道が混んでいたものだから、遅れました.', 'It pleads. The speaker is explaining themselves, which is why it appears mostly in apologies.', 'in-review', true, 335),
  ('gp-uedeha', 'lang-ja', 'ue-de', '〜上で', 'Verb-た / Noun の + 上で', 'lvl-ja-n2', 'conjunction', 'formal', 'After doing, and on that basis.', 'よく考えた上で、決めます.', 'Not merely "after". The first act informs the second, which is why 見た上で決める is deliberation and 見てから決める is only sequence.', 'in-review', true, 336),
  ('gp-ue-ni', 'lang-ja', 'ue-ni', '〜上に', 'Plain form + 上に', 'lvl-ja-n2', 'conjunction', 'formal', 'On top of that.', '安い上に、おいしい.', 'Both halves must lean the same way — two good things or two bad. Mixing them is what 反面 is for.', 'in-review', true, 337),
  ('gp-sue-ni', 'lang-ja', 'sue-ni', '〜末に', 'Verb-た / Noun の + 末に', 'lvl-ja-n2', 'conjunction', 'formal', 'After a long process.', '長時間の議論の末に、結論が出た.', '末 is an end point reached after effort. It cannot describe something quick, which is what distinguishes it from 後で.', 'in-review', true, 338),
  ('gp-agete', 'lang-ja', 'agaku', '〜あげく', 'Verb-た / Noun の + あげく', 'lvl-ja-n2', 'conjunction', 'formal', 'After all that — and it ended badly.', '迷ったあげく、買わなかった.', 'Same shape as 末に but the outcome is always unwelcome. 末に can end well; あげく cannot.', 'in-review', true, 339),
  ('gp-tsuide-ni', 'lang-ja', 'tsuide-ni', '〜ついでに', 'Plain form / Noun の + ついでに', 'lvl-ja-n2', 'conjunction', 'casual', 'While you''re at it.', '買い物のついでに、郵便局に寄った.', 'The second errand rides on the first. It cannot be the reason for going, only an addition once you are already out.', 'in-review', true, 340),
  ('gp-kuse-shite', 'lang-ja', 'yara', '〜やら〜やら', 'Noun + やら + Noun + やら', 'lvl-ja-n2', 'particle', 'casual', 'What with this and that.', '雨やら風やらで、大変だった.', 'A vaguer, more exasperated list than たり. It implies more of the same, and usually more than the speaker cares to enumerate.', 'in-review', true, 341),
  ('gp-mo-shinai', 'lang-ja', 'mo-shinai', '〜もしない', 'Verb stem + もしない', 'lvl-ja-n2', 'expression', 'casual', 'Doesn''t even.', '見もしないで批判する.', 'The も is what adds the reproach. 見ないで is neutral; 見もしないで is an accusation.', 'in-review', true, 342),
  ('gp-te-bakari-iru', 'lang-ja', 'te-bakari-iru', '〜てばかりいる', 'Verb-て + ばかりいる', 'lvl-ja-n2', 'expression', 'casual', 'Does nothing but.', '遊んでばかりいる.', 'A complaint about a habit. Unlike 〜ばかり on a noun, this one always disapproves of the doer.', 'in-review', true, 343),
  ('gp-te-tamaranai', 'lang-ja', 'te-tamaranai', '〜てたまらない', 'Verb-て / Adj-くて + たまらない', 'lvl-ja-n2', 'expression', 'casual', 'Unbearably.', '暑くてたまらない.', 'A physical or emotional state past enduring. 〜てしかたがない is its calmer twin, and 〜てならない the most written of the three.', 'in-review', true, 344),
  ('gp-te-shikata-ga-nai', 'lang-ja', 'te-shikata-ga-nai', '〜てしかたがない', 'Verb-て / Adj-くて + しかたがない', 'lvl-ja-n2', 'expression', 'casual', 'Can''t help feeling.', '気になってしかたがない.', 'From 仕方, "a way of doing" — there is no way to deal with it. Contracts to 〜てしょうがない in speech.', 'in-review', true, 345),
  ('gp-zu-ni-wa-irarenai', 'lang-ja', 'zu-ni-wa-irarenai', '〜ずにはいられない', 'Verb-ない stem + ずにはいられない', 'lvl-ja-n2', 'expression', 'formal', 'Cannot help doing.', '笑わずにはいられなかった.', 'A compulsion the speaker did not choose. する is irregular: せずにはいられない.', 'in-review', true, 346),
  ('gp-nakuteha-naranai', 'lang-ja', 'te-wa-naranai', '〜てはならない', 'Verb-て + はならない', 'lvl-ja-n2', 'expression', 'formal', 'Must not.', '忘れてはならない.', 'The register of law and principle. てはいけない forbids in the moment; てはならない forbids as a rule.', 'in-review', true, 347),
  ('gp-ni-atatte', 'lang-ja', 'ni-atatte', '〜に当たって', 'Plain present / Noun + に当たって', 'lvl-ja-n2', 'expression', 'formal', 'On the occasion of.', '開会に当たって、一言申し上げます.', 'Reserved for significant occasions, and always looking forward from the threshold of one. Speeches open with it.', 'in-review', true, 348),
  ('gp-ni-saishite', 'lang-ja', 'ni-saishite', '〜に際して', 'Plain present / Noun + に際して', 'lvl-ja-n2', 'expression', 'formal', 'At the time of.', '契約に際して、注意すべき点.', 'Close to に当たって, and slightly more formal. Documents prefer it; speeches prefer に当たって.', 'in-review', true, 349),
  ('gp-wo-hajime', 'lang-ja', 'wo-hajime', '〜をはじめ', 'Noun + をはじめ', 'lvl-ja-n2', 'expression', 'formal', 'Starting with — as the leading example.', '社長をはじめ、全社員が参加した.', 'It names the most prominent member of a group, then sweeps in the rest. Not a sequence, unlike 〜を皮切りに.', 'in-review', true, 350),
  ('gp-jou', 'lang-ja', 'jou', '〜上', 'Noun + 上', 'lvl-ja-n2', 'auxiliary', 'formal', 'From the standpoint of.', '法律上、問題ない. 健康上の理由.', 'Read じょう. It narrows a claim to one domain, which is why disclaimers and official reasons lean on it.', 'in-review', true, 351),
  ('gp-ge', 'lang-ja', 'ge', '〜げ', 'Adj stem + げ', 'lvl-ja-n2', 'auxiliary', 'formal', 'Looking, with an air of.', '悲しげな顔. 不安げに.', 'Only for appearances of feeling, and only about others. Literary where っぽい is colloquial.', 'in-review', true, 352),
  ('gp-mamire', 'lang-ja', 'mamire', '〜まみれ', 'Noun + まみれ', 'lvl-ja-n2', 'auxiliary', 'casual', 'Smeared in.', '汗まみれ. 血まみれ.', 'Narrower than だらけ: it needs something that actually clings — sweat, mud, blood, dust. 間違いまみれ is wrong; 間違いだらけ is right.', 'in-review', true, 353),
  ('gp-zukume', 'lang-ja', 'zukume', '〜ずくめ', 'Noun + ずくめ', 'lvl-ja-n2', 'auxiliary', 'formal', 'Nothing but.', 'いいことずくめ. 黒ずくめの服装.', 'Unlike だらけ it is not negative — it simply says everything was of one kind, and often that is a good thing.', 'in-review', true, 354)
